import { isPromise } from 'node:util/types';
import { CliError, CliErrorCode } from '@wix/cli-error';
import { z } from 'zod';

const PLATFORM_LINK_TYPES = ['site', 'dashboard', 'editor'] as const;

export type PlatformLinkType = (typeof PLATFORM_LINK_TYPES)[number];

/** Commands that display platform links or write them to `.wix/topology.json`. */
export type PlatformLinkCommand = 'dev' | 'preview' | 'release';

const platformLinkItemSchema = z.object({
  platform: z.enum(PLATFORM_LINK_TYPES),
  label: z.string().trim().min(1, {
    message: 'Label must be a non-empty string.',
  }),
  url: z.string().url(),
});

const platformLinksSchema = z
  .array(platformLinkItemSchema)
  .superRefine((links, ctx) => {
    const seenPlatforms = new Set<PlatformLinkType>();
    for (const [index, link] of links.entries()) {
      if (seenPlatforms.has(link.platform)) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          path: [index, 'platform'],
          message: `"${link.platform}" link appears more than once.`,
        });
      }
      seenPlatforms.add(link.platform);
    }
  });

export type PlatformLinkItem = z.infer<typeof platformLinkItemSchema>;

export interface PlatformLinkCtx {
  /** The command that is resolving the links. */
  cmd: PlatformLinkCommand;
  overrideId: string;
  appId: string;
  siteId?: string;
  /**
   * Links planned for rendering, in render order.
   * Reflects changes made by earlier plugins.
   */
  links: readonly PlatformLinkItem[];
}

/**
 * Returns the platform links (site, dashboard, editor) displayed by the Wix
 * CLI in the terminal and written to `.wix/topology.json`.
 *
 * - Return `ctx.links` as is to keep the current links.
 * - Change `label` / `url` of an item to override it.
 * - Omit an item to hide the link. Later plugins will not see it.
 * - Order of the returned list is the render order.
 *
 * Each `platform` may appear at most once. Only known platforms are accepted.
 * The CLI may still hide a returned link based on its own conditions, and
 * only known platforms are written to `.wix/topology.json`.
 *
 * Expected to be a pure and synchronous function. The CLI may call it any
 * number of times per command.
 */
export type PlatformLinksHandler = (ctx: PlatformLinkCtx) => PlatformLinkItem[];

export interface PlatformLinksPlugin {
  name: string;
  platformLinks: PlatformLinksHandler;
}

function parsePlatformLinks(
  result: unknown,
  pluginName: string
): PlatformLinkItem[] {
  const parsed = platformLinksSchema.safeParse(result);
  if (!parsed.success) {
    throw new CliError({
      code: CliErrorCode.PluginInvalidPlatformLinksResult({
        pluginName,
        reason: parsed.error.message,
      }),
      cause: parsed.error,
    });
  }
  return parsed.data;
}

export function resolvePlatformLinks(
  plugins: readonly PlatformLinksPlugin[],
  ctx: PlatformLinkCtx
): PlatformLinkItem[] {
  let current: PlatformLinkItem[] = ctx.links.map((link) => ({ ...link }));

  for (const plugin of plugins) {
    let result: unknown;
    try {
      result = plugin.platformLinks({ ...ctx, links: current });
    } catch (error) {
      throw new CliError({
        code: CliErrorCode.PluginInvalidPlatformLinksResult({
          pluginName: plugin.name,
          reason: `"platformLinks" threw an error.`,
        }),
        cause: error,
      });
    }

    if (isPromise(result)) {
      // Consume any rejection while reporting the synchronous API violation.
      void result.catch(() => {});
      throw new CliError({
        code: CliErrorCode.PluginInvalidPlatformLinksResult({
          pluginName: plugin.name,
          reason: '"platformLinks" must be synchronous; received a Promise.',
        }),
        cause: null,
      });
    }

    current = parsePlatformLinks(result, plugin.name);
  }

  return current;
}
